import tempfile
import torch
from topologies import Trainer, build, synth
root = tempfile.mkdtemp()
@synth.generator
def samples(ctx):
    features = torch.randn(4, generator=ctx.rng.torch)
    return {"features": synth.Tensor(features), "labels": int(features[:3].argmax())}
ds = synth.Spec("evidential-classifier", generator=samples, size=12, splits={"train": 1.0}, seed=11, root=root, monitor="none").run()
train = ds.for_recipe("tabular-classify", split="train")
class EvidenceModel(torch.nn.Module):
    def __init__(self):
        super().__init__()
        self.network = build("mlp", "tiny", in_features=4, out_features=3)
    def forward(self, features):
        return torch.nn.functional.softplus(self.network(features))
model = EvidenceModel()
trainer = Trainer(model, train, recipe="tabular-classify", recipe_config={"loss": "evidential", "loss_kwargs": {"annealing_coef": 0.5, "reduction": "sum"}}, batch_size=4, max_epochs=1, device="cpu")
trainer.fit()
